const GoogleWorkProductEditor=lazy(()=>import('./google_editor').then(module=>({default:module.GoogleWorkProductEditor})));
export type ConsultantReportDocument={id:number;visit_id:number|null;activity_id?:number|null;document_type:string;file_name:string;status:string;remarks?:string|null;version?:number;uploaded_at?:string;uploaded_by?:number;editor_provider?:string|null;google_file_url?:string|null};
type JobCard={id:number;number:string;location:string;project_start_date:string;project_end_date:string;required_md:string;hours_per_manday:string;required_hours:string;status:string};type Milestone={id:number;code:string;name:string;planned_visits:number;planned_mandays?:string|null;responsible_consultant_id?:number|null;responsible_consultant_name?:string|null;consultant_allocations?:{consultant_id:number;consultant_name:string;allocated_mandays:string}[];assigned_consultants?:number;estimated_working_days?:string|null;actual_visits:number;progress:string;status:string;payment_status?:string;review_status?:string;review_cycle?:number;review_remarks?:string|null;start_date?:string|null;closing_date?:string|null;payment_date?:string|null;portal_report_submission_date?:string|null};type Visit={id:number;job_card_id:number;job_card_number?:string;milestone_id:number;planned_visit_id?:number|null;visit_number:number;visit_date:string;start_time?:string|null;end_time?:string|null;location?:string|null;findings?:string|null;consultant_id?:number|null;co_consultant_id?:number|null;subject_expert_id?:number|null;working_minutes:number;work_details:string;rating_code:string;status:string;rejection_reason?:string;created_by:number;attachment_name?:string;remarks?:string};type Document={id:number;job_card_id:number;job_card_number?:string;document_type:string;file_name:string;version:number;status:string;remarks?:string;uploaded_by:number};type MyRecordDocument={id:number;owner_job_card_id:number|null;job_card_number:string;document_type:string;file_name:string;version:number;status:string;remarks:string|null;uploaded_at:string;editor_provider:string|null;google_file_url:string|null};type Approval={id:number;stage:string;cycle:number;decision:string;comment?:string};type Notice={id:number;message:string;link?:string;read_at?:string;created_at:string};type Activity={id:number;action:string;entity_type:string;details?:string;created_at:string};type Mandays={completed_minutes:number;completed_hours:string;remaining_hours:string;completed_md:string;remaining_minutes:string;remaining_md:string;progress:string;overrun:boolean};type Assignment={user_id:number;full_name:string;assignment_type:string;milestone_code?:string|null};
const err=(e:unknown)=>e instanceof Error?e.message:'Unable to complete request.';
const milestoneTeamLabel=(milestone:Milestone)=>milestone.consultant_allocations?.map(item=>`${item.consultant_name} (${item.allocated_mandays} MD)`).join(', ')||milestone.responsible_consultant_name||'Unassigned';
function useLoad<T>(path:string){const [data,setData]=useState<T|null>(null);const [error,setError]=useState('');const reload=()=>api<T>(path).then(value=>{setData(value);setError('')}).catch((e:unknown)=>setError(err(e)));useEffect(()=>{reload()},[path]);return {data,error,reload}}

export function Registration(){
  const [message,setMessage]=useState('');
  async function submit(e:FormEvent<HTMLFormElement>){
    e.preventDefault();
    try{
      await api('/api/auth/register',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});
      setMessage('Registration submitted. An administrator must activate your account before you can sign in.')
    }catch(e){
      setMessage(err(e))
    }
  }
  return (
    <GuestLayout>
      <div className="login-card-inner">
        <span className="form-eyebrow">CONSULTANT REGISTRATION</span>
        <h2 className="form-title">Create account</h2>
        <p className="form-description">Onboarding requires administrator approval and activation.</p>
        
        <form onSubmit={submit} className="form-grid">
          <Field label="Full name" name="full_name" required placeholder="e.g. Rahul Sharma"/>
          <Field label="Email" name="email" type="email" required placeholder="name@dmastru.com"/>
          <Field label="Mobile number" name="mobile" placeholder="e.g. +91 99999 99999"/>
          <Field label="Consultant ID" name="consultant_id" placeholder="e.g. CON-2026-001"/>
          <Field label="Password" name="password" type="password" minLength={8} required placeholder="At least 8 characters"/>
          <Field label="Confirm password" name="confirm_password" type="password" minLength={8} required placeholder="Repeat password"/>
          
          <Button type="submit">Register Consultant</Button>
        </form>
        
        {message && (
          <p role="status" className={message.includes('submitted') ? 'form-success-info' : 'form-error'}>
            {message}
          </p>
        )}
        
        <p className="form-footer-link">
          Already have an account? <Link to="/login">Back to sign in</Link>
        </p>
      </div>
    </GuestLayout>
  );
}

export function UserDashboard(){type ActionItem={id:string;action_number:string;title:string;job_card_id:number|null;due_at?:string|null;status:string};const dash=useLoad<{kpis:Record<string,number|string>;projects:JobCard[];my_actions:ActionItem[]}>('/api/dashboard/user');const metrics:[string,string][]=[['assigned_job_cards','My Job Cards'],['active_milestones','Active Milestones'],['due_today_tasks','Tasks Due Today'],['overdue_tasks','Overdue Tasks'],['upcoming_visits','Upcoming Visits'],['pending_submissions','Pending Submissions'],['planned_mandays','Planned Mandays'],['actual_mandays','Actual Mandays']];return <Page title="My Dashboard"><UserError text={dash.error}/><div className="stat-grid dashboard-metrics">{metrics.map(([key,label])=><Card key={key}><p className="muted">{label}</p><strong className="stat">{dash.data?.kpis[key]??0}{key.endsWith('mandays')?' MD':''}</strong></Card>)}</div><div className="dashboard-shortcuts"><Link className="button primary" to="/user/visits">My Planner</Link><Link className="button quiet" to="/user/documents">My Documents</Link><Link className="button quiet" to="/referrals">My Referrals</Link></div><div className="dashboard-overview-grid"><Card title={`Automated workflow tasks - ${dash.data?.my_actions.length??0}`}><div className="dashboard-list">{(dash.data?.my_actions??[]).slice(0,3).map(a=><article className="crm-record" key={a.id}><strong>{a.title}</strong><p>{a.due_at?`Due ${new Date(a.due_at).toLocaleDateString()}`:'No due date'} <Status>{a.status}</Status></p>{a.job_card_id&&<Link to={`/job-cards/${a.job_card_id}`}>Open Job Card</Link>}</article>)}{dash.data?.my_actions.length===0&&<p className="muted">No workflow tasks need your attention.</p>}</div></Card><Card title="My Job Cards"><div className="dashboard-list">{(dash.data?.projects??[]).slice(0,3).map(card=><article className="dashboard-row" key={card.id}><Link to={`/job-cards/${card.id}`}><strong>{card.number}</strong></Link><span>{card.location} - {card.status}</span></article>)}{!dash.data?.projects.length&&<p className="muted">No Job Cards assigned.</p>}</div><DashboardLink to="/user/job-cards" icon="folder">All Job Cards</DashboardLink></Card></div></Page>}
export function MyJobCards({mandaysOnly=false}:{mandaysOnly?:boolean}){const cards=useLoad<JobCard[]>('/api/job-cards');const [params,setParams]=useSearchParams();const requested=params.get('card');const [selected,setSelected]=useState<JobCard|null>(null);useEffect(()=>{if(requested)api<JobCard>(`/api/job-cards/${requested}`).then(setSelected).catch(e=>alert(err(e)))},[requested]);function close(){setSelected(null);setParams(current=>{current.delete('card');return current},{replace:true})}function open(card:JobCard){setSelected(card);setParams(current=>{current.set('card',String(card.id));return current},{replace:true})}return <Page title={mandaysOnly?'Mandays':'My Job Cards'}><UserError text={cards.error}/>{mandaysOnly&&<p className="muted">Choose one of your assigned Job Cards to review planned, actual, and remaining mandays.</p>}<Rows cards={cards.data??[]} onOpen={open}/>{selected&&<CardDetail card={selected} close={close} reload={cards.reload}/>}</Page>}
function Rows({cards,onOpen}:{cards:JobCard[];onOpen?:(c:JobCard)=>void}){
  return <div className="table-wrap mobile-cards"><table>
    <thead><tr><th>Job Card</th><th>Location</th><th>Dates</th><th>Status</th><th>Action</th></tr></thead>
    <tbody>{cards.length?cards.map(c=><tr key={c.id}>
      <td data-label="Job Card"><strong>{c.number}</strong></td>
      <td data-label="Location">{c.location}</td>
      <td data-label="Dates">{c.project_start_date} - {c.project_end_date}</td>
      <td data-label="Status"><Status>{c.status}</Status></td>
      <td data-label="Action">{onOpen&&<Button variant="secondary" onClick={()=>onOpen(c)}>Open</Button>}</td>
    </tr>):<tr><td colSpan={5} className="muted">No Job Cards have been assigned to you yet.</td></tr>}</tbody>
  </table></div>
}
