 const plan=availablePlans.find(item=>String(item.id)===plannedVisitId);
 const milestone=milestones.find(item=>item.id===plan?.milestone_id);
 async function save(e:FormEvent<HTMLFormElement>){e.preventDefault();if(!plan){setError('Plan a visit in My Planner before submitting a visit report.');return}setBusy(true);setError('');const f=new FormData(e.currentTarget),d:Record<string,unknown>=Object.fromEntries(f);d.planned_visit_id=Number(plan.id);d.milestone_id=plan.milestone_id;d.visit_date=plan.visit_date;d.hours=Number(d.hours);d.minutes=Number(d.minutes);d.start_time=d.start_time||null;d.end_time=d.end_time||null;d.location=d.location||plan.location||card.location;d.findings=d.findings||null;const file=f.get('attachment') as File;if(file?.size){try{d.attachment_name=file.name;d.attachment_mime_type=file.type;d.attachment_base64=await read(file)}catch(e){setError(err(e));setBusy(false);return}}else{delete d.attachment_name;delete d.attachment_mime_type;delete d.attachment_base64}try{const visit=await api<Visit>(`/api/job-cards/${card.id}/visits/draft`,{method:'POST',body:JSON.stringify(d)});if(mode==='submit')await api(`/api/visits/${visit.id}/submit`,{method:'POST'});done()}catch(e){setError(err(e))}finally{setBusy(false)}}
 return <Card title="Submit visit report">{error&&<p className="form-error" role="alert">{error}</p>}{!availablePlans.length?<><p className="muted">A visit must be planned before its report can be submitted.</p><Link className="button secondary" to="/user/visits">Open My Planner</Link></>:<form className="form-grid" onSubmit={save}><label className="field wide"><span>Planned visit</span><select name="planned_visit_id" value={plannedVisitId} onChange={event=>setPlannedVisitId(event.target.value)} required><option value="">Select a planned visit</option>{availablePlans.map(item=><option value={item.id} key={item.id}>{item.visit_date} | {item.milestone_code} {item.milestone_name} | {item.objective}</option>)}</select></label>{plan&&<><p className="muted wide">{milestone?.code} {milestone?.name} | {plan.visit_date} | {plan.location} | Planned team: {[plan.consultant_name,plan.co_consultant_id?`Consultant #${plan.co_consultant_id}`:null,plan.subject_expert_id?`Consultant #${plan.subject_expert_id}`:null].filter(Boolean).join(', ')}</p><input type="hidden" name="milestone_id" value={plan.milestone_id}/><input type="hidden" name="visit_date" value={plan.visit_date}/><Field label="Actual start time (optional)" name="start_time" type="time"/><Field label="Actual end time (optional)" name="end_time" type="time"/><Field key={plan.id} label="Location" name="location" defaultValue={plan.location}/><Field label="Hours (if no times)" name="hours" type="number" min="0" defaultValue="0"/><Field label="Minutes" name="minutes" type="number" min="0" max="59" defaultValue="0"/><label className="field"><span>Rating</span><select name="rating_code"><option value="A">A - Excellent</option><option value="B">B - Very Good</option><option value="C">C - Good</option><option value="D">D - Poor</option><option value="E">E - Not Satisfactory</option></select></label><label className="field wide"><span>Work details</span><textarea name="work_details" minLength={3} required/></label><label className="field wide"><span>Findings</span><textarea name="findings"/></label><label className="field wide"><span>Remarks</span><textarea name="remarks"/></label><label className="field wide"><span>Attachment (required except M1, where visit tasks require evidence)</span><input name="attachment" type="file" accept=".pdf,.png,.jpg,.jpeg,.docx,.xlsx"/></label><div className="actions"><Button type="submit" variant="secondary" disabled={busy} onClick={()=>setMode('draft')}>Save draft</Button><Button type="submit" disabled={busy} onClick={()=>setMode('submit')}>{busy?'Saving...':'Submit visit'}</Button></div></>}</form>}</Card>
